#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "ScoreTracker was a raw UObject pointer (UArenaScoreTracker*) created with NewObject but not stored as a UPROPERTY, so the garbage collector could collect it. The log shows 'Collecting garbage: 412 objects purged' at 21:05:13, then the crash at 21:05:27 in UArenaScoreTracker::AddPoints() reading address 0xffffffffffffffff — a dangling pointer. Fixed by making ScoreTracker a UPROPERTY TObjectPtr in ArenaGameMode.h.",
  "no_colors_cause": "The palette asset /Game/Data/Palettes/DA_Primary was not included in the packaged build. DefaultGame.ini only listed /Game/Data/Effects in DirectoriesToAlwaysCook; /Game/Data/Palettes was never cooked, so LoadObject returned null at runtime and the game fell back to gray. Fixed by adding /Game/Data/Palettes to DirectoriesToAlwaysCook."
}
